  INSERT INTO public.lampas_confessional_questions
    (document_id, number, number_label, question, answer, doctrine_tags, bible_references, sort_order, metadata)
  VALUES
    (v_doc_id, 1, '1', 'Qual é a tua única consolação, tanto na vida como na morte?', 'Que eu, com corpo e alma, tanto na vida como na morte, não sou meu, mas pertenço ao meu fiel Salvador Jesus Cristo, que com seu precioso sangue pagou completamente por todos os meus pecados e me redimiu do poder do diabo; que ele também me guarda de tal modo que, sem a vontade de meu Pai celestial, nenhum fio de cabelo pode cair da minha cabeça; antes, tudo deve cooperar para a minha salvação. Por isso, pelo seu Espírito Santo, ele também me assegura a vida eterna e me torna de coração disposto e pronto a viver para ele daí em diante.', ARRAY['consolação','pertencer a Cristo','soteriologia','asseguração'], ARRAY['1 Coríntios 6.19-20','Romanos 8.38-39'], 1, '{"full_seed":true}'::jsonb),
    (v_doc_id, 2, '2', 'Quantas coisas precisas saber para que, nesta consolação, possas viver e morrer bem-aventurado?', 'Três coisas: primeiro, quão grande é o meu pecado e miséria; segundo, como sou redimido de todos os meus pecados e miséria; terceiro, como devo ser grato a Deus por tal redenção.', ARRAY['pecado','redenção','gratidão'], ARRAY['Mateus 11.28-30','João 17.3','Efésios 5.10'], 2, '{"full_seed":true}'::jsonb),
    (v_doc_id, 3, '3', 'Onde conheces a tua miséria?', 'Na lei de Deus.', ARRAY['lei','pecado','miséria'], ARRAY['Romanos 3.20'], 3, '{"full_seed":true}'::jsonb),
    (v_doc_id, 4, '4', 'O que a lei de Deus requer de nós?', 'Cristo nos ensina isso em resumo em Mateus 22.37-40: "Amarás ao Senhor, teu Deus, de todo o teu coração, e de toda a tua alma, e de todo o teu entendimento, e de todo o teu poder. Este é o primeiro e grande mandamento. O segundo semelhante a este é: Amarás ao teu próximo como a ti mesmo. Destes dois mandamentos dependem toda a lei e os profetas."', ARRAY['lei','amor a Deus','amor ao próximo'], ARRAY['Mateus 22.37-40','Deuteronômio 6.5'], 4, '{"full_seed":true}'::jsonb),
    (v_doc_id, 5, '5', 'Podes cumprir isso perfeitamente?', 'Não; pois por natureza sou propenso a odiar a Deus e ao próximo.', ARRAY['depravação total','incapacidade','pecado'], ARRAY['Romanos 3.10-12','Gênesis 6.5'], 5, '{"full_seed":true}'::jsonb),
    (v_doc_id, 6, '6', 'Deus criou o homem tão mau e perverso?', 'Não; antes Deus criou o homem bom e segundo a sua imagem, isto é, em verdadeira justiça e santidade, para que conhecesse corretamente a Deus seu Criador, o amasse de coração e vivesse com ele em eterna bem-aventurança para louvar e glorificar a Deus.', ARRAY['criação','imago Dei','bondade original'], ARRAY['Gênesis 1.31','Efésios 4.24'], 6, '{"full_seed":true}'::jsonb),
    (v_doc_id, 7, '7', 'De onde, pois, vem essa natureza corrupta do homem?', 'Da queda e desobediência dos nossos primeiros pais, Adão e Eva, no paraíso; daí nossa natureza ficou tão corrompida que todos somos concebidos e nascidos em pecado.', ARRAY['queda','pecado original','corrupção'], ARRAY['Gênesis 3.6','Salmo 51.5'], 7, '{"full_seed":true}'::jsonb),
    (v_doc_id, 8, '8', 'Somos, porém, tão corrompidos que somos absolutamente incapazes de algum bem e propensos a todo o mal?', 'Sim, a não ser que sejamos regenerados pelo Espírito de Deus.', ARRAY['depravação total','regeneração','Espírito Santo'], ARRAY['João 3.5','Romanos 8.7'], 8, '{"full_seed":true}'::jsonb),
    (v_doc_id, 9, '9', 'Não faz, pois, Deus injustiça ao homem, exigindo-lhe em sua lei o que ele não pode fazer?', 'Não; pois Deus criou o homem de tal modo que ele era capaz de fazê-lo; mas o homem, a instigação do diabo, por seu próprio livre-arbítrio, se subtraiu a si e a todos os seus descendentes desse dom de Deus.', ARRAY['lei','justiça divina','queda','livre-arbítrio'], ARRAY['Gênesis 1.31','Romanos 5.12'], 9, '{"full_seed":true}'::jsonb),
    (v_doc_id, 10, '10', 'Quer Deus deixar impune tal desobediência e apostasia?', 'De maneira alguma; antes, se ira terrivelmente, tanto com o pecado herdado como com o atual, e quer puni-los segundo o juízo justo, temporal e eternamente, como declarou: "Maldito todo aquele que não perseverar em fazer tudo o que está escrito no livro da lei."', ARRAY['ira de Deus','julgamento','lei'], ARRAY['Romanos 1.18','Gálatas 3.10'], 10, '{"full_seed":true}'::jsonb),
    (v_doc_id, 11, '11', 'Deus não é também misericordioso?', 'Deus é certamente misericordioso, mas também é justo; por isso, sua justiça exige que o pecado que é cometido contra a soberana majestade de Deus seja punido também com o máximo, isto é, com punição eterna no corpo e na alma.', ARRAY['misericórdia','justiça divina','punição eterna'], ARRAY['Êxodo 34.7','Salmo 7.11'], 11, '{"full_seed":true}'::jsonb),
    (v_doc_id, 12, '12', 'Já que, pois, pelo juízo justo de Deus, merecemos punição temporal e eterna, como podemos escapar dessa punição e retornar à graça?', 'Deus quer que se faça satisfação à sua justiça; portanto, ou nós mesmos ou outro por nós temos que satisfazer plenamente.', ARRAY['satisfação','justiça divina','redenção'], ARRAY['Romanos 8.4','Mateus 5.26'], 12, '{"full_seed":true}'::jsonb),
    (v_doc_id, 13, '13', 'Podemos nós mesmos fazer tal satisfação?', 'De forma alguma; antes ainda cada dia aumentamos nossa dívida.', ARRAY['incapacidade humana','satisfação','pecado'], ARRAY['Jó 9.2-3','Salmo 130.3'], 13, '{"full_seed":true}'::jsonb),
    (v_doc_id, 14, '14', 'Pode alguma criatura fazer tal satisfação por nós?', 'Não; porque, primeiro, Deus não quer punir por causa do pecado do homem nenhuma outra criatura; segundo, nenhuma criatura simples pode suportar a ira de Deus contra o pecado e nos redimir de tal ira.', ARRAY['satisfação','mediação','encarnação'], ARRAY['Hebreus 2.14-15','Salmo 49.7-8'], 14, '{"full_seed":true}'::jsonb),
    (v_doc_id, 15, '15', 'Que mediador e redentor, pois, precisamos buscar?', 'Um que seja verdadeiro homem e totalmente justo e, ao mesmo tempo, mais poderoso que todas as criaturas, isto é, que seja também verdadeiro Deus.', ARRAY['mediador','Encarnação','duas naturezas','Redentor'], ARRAY['1 Timóteo 2.5','Isaías 9.6'], 15, '{"full_seed":true}'::jsonb),
    (v_doc_id, 16, '16', 'Por que ele tem que ser verdadeiro homem e totalmente justo?', 'Porque a justiça de Deus requer que a mesma natureza humana que pecou pague o pecado; mas aquele que é um pecador não pode pagar por outros.', ARRAY['Encarnação','impecabilidade','satisfação','duas naturezas'], ARRAY['Romanos 5.15','Hebreus 2.17'], 16, '{"full_seed":true}'::jsonb),
    (v_doc_id, 17, '17', 'Por que ele tem que ser ao mesmo tempo verdadeiro Deus?', 'Para que, pelo poder de sua divindade, pudesse suportar em sua humanidade o peso da ira de Deus, conquistar e restituir-nos a justiça e a vida.', ARRAY['divindade de Cristo','duas naturezas','expiação'], ARRAY['Atos 2.24','João 3.16'], 17, '{"full_seed":true}'::jsonb),
    (v_doc_id, 18, '18', 'Mas quem é esse mediador, que é ao mesmo tempo verdadeiro Deus e verdadeiro homem e totalmente justo?', 'Nosso Senhor Jesus Cristo, que nos foi dado para perfeita redenção e justiça; o qual é a sabedoria de Deus e sua imagem.', ARRAY['Jesus Cristo','mediador','Encarnação'], ARRAY['1 João 5.20','1 Coríntios 1.30'], 18, '{"full_seed":true}'::jsonb),
    (v_doc_id, 19, '19', 'De onde sabes isso?', 'Do santo Evangelho, que Deus mesmo primeiramente revelou no paraíso, depois o fez proclamar pelos santos patriarcas e profetas, prefigurar pelos sacrifícios e demais cerimônias da lei, e finalmente cumprir por seu amado Filho.', ARRAY['Evangelho','proto-evangelho','profecia messiânica'], ARRAY['Gênesis 3.15','Gálatas 4.4'], 19, '{"full_seed":true}'::jsonb),
    (v_doc_id, 20, '20', 'Serão, pois, todos os homens salvos outra vez por Cristo, como também foram condenados por Adão?', 'Não; somente os que pela verdadeira fé são enxertados nele e recebem todos os seus benefícios.', ARRAY['eleição','fé','salvação','Adão e Cristo'], ARRAY['João 1.12','Romanos 11.20'], 20, '{"full_seed":true}'::jsonb),
    (v_doc_id, 21, '21', 'O que é a verdadeira fé?', 'A verdadeira fé é não apenas um conhecimento certo pelo qual tenho como verdadeiro tudo o que Deus nos revelou em sua Palavra, mas também uma firme confiança que o Espírito Santo cria em meu coração pelo Evangelho, de que Deus não só a outros, mas também a mim concede remissão de pecados, eterna justiça e salvação, por pura graça, somente pela mérecia de Cristo.', ARRAY['fé','confiança','Espírito Santo','asseguração'], ARRAY['Romanos 10.17','Romanos 4.18-21','Gálatas 2.20'], 21, '{"full_seed":true}'::jsonb),
    (v_doc_id, 22, '22', 'O que um cristão deve crer?', 'Tudo o que nos é prometido no Evangelho, que os artigos de nossa fé católica e indubitável nos ensinam em resumo.', ARRAY['credo','fé','Evangelho'], ARRAY['Mateus 28.19','João 20.31'], 22, '{"full_seed":true}'::jsonb),
    (v_doc_id, 23, '23', 'Quais são esses artigos?', 'Creio em Deus Pai todo-poderoso, criador do céu e da terra. E em Jesus Cristo, seu único Filho, nosso Senhor; que foi concebido pelo Espírito Santo, nasceu da Virgem Maria; padeceu sob Pôncio Pilatos, foi crucificado, morto e sepultado; desceu ao inferno; no terceiro dia ressurgiu dos mortos; subiu ao céu, está sentado à destra de Deus Pai todo-poderoso; donde há de vir a julgar os vivos e os mortos. Creio no Espírito Santo, na santa Igreja universal, na comunhão dos santos, na remissão dos pecados, na ressurreição dos mortos e na vida eterna. Amém.', ARRAY['credo apostólico','Trindade','soteriologia'], ARRAY['Mateus 28.19'], 23, '{"full_seed":true}'::jsonb),
    (v_doc_id, 24, '24', 'Como estão divididos esses artigos?', 'Em três partes: a primeira é sobre Deus Pai e nossa criação; a segunda, sobre Deus Filho e nossa redenção; a terceira, sobre Deus Espírito Santo e nossa santificação.', ARRAY['Trindade','criação','redenção','santificação'], ARRAY['1 Pedro 1.2'], 24, '{"full_seed":true}'::jsonb),
    (v_doc_id, 25, '25', 'Já que há um só Deus, por que mencionas três, Pai, Filho e Espírito Santo?', 'Porque Deus assim se revelou em sua Palavra: que estas três distintas pessoas são um só Deus verdadeiro e eterno.', ARRAY['Trindade','pessoas divinas','monoteísmo'], ARRAY['Mateus 3.16-17','Mateus 28.19','2 Coríntios 13.13'], 25, '{"full_seed":true}'::jsonb),
    (v_doc_id, 26, '26', 'O que crês quando dizes: "Creio em Deus Pai todo-poderoso, Criador do céu e da terra"?', 'Que o eterno Pai de nosso Senhor Jesus Cristo, que do nada criou o céu, a terra e tudo o que neles há, que também sustenta e governa essas coisas pelo seu eterno conselho e providência, é por causa de Cristo meu Deus e Pai, em quem confio tanto que não duvido que ele me proverá de tudo o que é necessário para o corpo e a alma, e também fará com que os males que enviar sobre mim nesta vida de vale de lágrimas resultem em meu bem; pois ele pode fazer isso como Deus todo-poderoso e também quer fazê-lo como Pai fiel.', ARRAY['Pai','providência','confiança','criação'], ARRAY['Mateus 6.25-26','Romanos 8.28'], 26, '{"full_seed":true}'::jsonb),
    (v_doc_id, 27, '27', 'O que entendes pela providência de Deus?', 'O poder todo-poderoso e onipresente de Deus pelo qual ele sustenta e governa, como que com a sua mão, o céu e a terra com todas as criaturas, de modo que a erva e a folhagem, a chuva e a seca, anos férteis e estéreis, comida e bebida, saúde e doença, riqueza e pobreza, e tudo o mais, nos vêm não por acidente, mas pela sua mão paternal.', ARRAY['providência','soberania','governo divino'], ARRAY['Hebreus 1.3','Provérbios 16.33'], 27, '{"full_seed":true}'::jsonb),
    (v_doc_id, 28, '28', 'Que proveito nos traz o conhecimento da criação e da providência de Deus?', 'Que tenhamos paciência na adversidade, que sejamos gratos na prosperidade e que para o futuro tenhamos boa confiança em nosso Deus fiel, de que nada nos separará de seu amor, pois toda a criatura está tão em suas mãos que sem a sua vontade nem pode mover-se nem mover-nos.', ARRAY['providência','paciência','confiança','amor de Deus'], ARRAY['Romanos 5.3-4','1 Tessalonicenses 5.18'], 28, '{"full_seed":true}'::jsonb),
    (v_doc_id, 29, '29', 'Por que o Filho de Deus é chamado Jesus, isto é, Salvador?', 'Porque nos salva de todos os nossos pecados e porque em nenhum outro se deve buscar e encontrar alguma salvação.', ARRAY['Jesus','salvação','nome de Cristo'], ARRAY['Mateus 1.21','Atos 4.12'], 29, '{"full_seed":true}'::jsonb),
    (v_doc_id, 30, '30', 'Creem, pois, em Jesus, único Salvador, os que buscam sua bem-aventurança e salvação junto a santos, em si mesmos ou em outro lugar?', 'Não; pois, se bem que se vangloriem nele de palavra, de fato negam o único Salvador Jesus, pois Jesus ou não é um Salvador completo ou é um Salvador completo, e aquele que recebe esse Salvador pela verdadeira fé tem nele tudo o que é necessário para a salvação.', ARRAY['Jesus','salvação exclusiva','mérito humano'], ARRAY['Colossenses 1.19','João 14.6'], 30, '{"full_seed":true}'::jsonb),
    (v_doc_id, 31, '31', 'Por que é chamado Cristo, isto é, Ungido?', 'Porque ele foi ordenado pelo Pai e ungido com o Espírito Santo para ser nosso sumosacerdote principal, que nos redimiu por seu sacrifício único e sempre intercede pelo nosso favor diante do Pai; e para ser nosso Profeta principal, que nos revela o perfeito conselho de Deus para nossa redenção; e para ser nosso Rei eterno, que nos governa com sua Palavra e Espírito e nos defende e conserva na redenção conquistada.', ARRAY['Cristo','tríplice ofício','profeta','sacerdote','rei'], ARRAY['Hebreus 7.17','Atos 3.22','Salmo 2.6'], 31, '{"full_seed":true}'::jsonb),
    (v_doc_id, 32, '32', 'Por que és chamado cristão?', 'Porque sou membro de Cristo pela fé e assim participante de sua unção, para que eu confesse o seu nome, me ofereça como sacrifício vivo de gratidão a ele, e com boa consciência lute nesta vida contra o pecado e o diabo, e depois reine com ele eternamente sobre todas as criaturas.', ARRAY['cristão','participação em Cristo','tríplice ofício'], ARRAY['1 João 2.27','1 Pedro 2.9'], 32, '{"full_seed":true}'::jsonb),
    (v_doc_id, 33, '33', 'Por que ele é chamado Filho único de Deus, já que somos também filhos de Deus?', 'Porque Cristo é o único Filho eterno e natural de Deus; ao passo que nós somos filhos de Deus por adoção, por graça, por amor a ele.', ARRAY['Filho de Deus','filiação eterna','adoção'], ARRAY['João 1.14','João 1.18','Romanos 8.15'], 33, '{"full_seed":true}'::jsonb),
    (v_doc_id, 34, '34', 'Por que o chamas nosso Senhor?', 'Porque ele nos redimiu, em corpo e alma, do poder do pecado, de toda dominação do diabo, e nos tornou sua propriedade, não com ouro ou prata, mas com seu precioso sangue.', ARRAY['senhorio de Cristo','redenção','expiação'], ARRAY['1 Pedro 1.18-19','1 Coríntios 6.20'], 34, '{"full_seed":true}'::jsonb),
    (v_doc_id, 35, '35', 'O que significa "concebido pelo Espírito Santo, nascido da Virgem Maria"?', 'Que o Filho eterno de Deus, que existe e permanece verdadeiro e eterno Deus, tomou para si a natureza humana da carne e do sangue da Virgem Maria pelo Espírito Santo, para que também fosse a verdadeira semente de Davi, em tudo semelhante a seus irmãos, exceto no pecado.', ARRAY['Encarnação','virgem Maria','Espírito Santo','impecabilidade'], ARRAY['Lucas 1.35','João 1.14','Hebreus 2.17'], 35, '{"full_seed":true}'::jsonb),
    (v_doc_id, 36, '36', 'Que proveito te traz a santa concepção e o nascimento de Cristo?', 'Que ele é nosso mediador e que com sua inocência e perfeita santidade cobre diante de Deus minha culpa e pecado, nos quais fui concebido.', ARRAY['Encarnação','mediação','impecabilidade'], ARRAY['Romanos 8.3-4','2 Coríntios 5.21'], 36, '{"full_seed":true}'::jsonb),
    (v_doc_id, 37, '37', 'O que entendes pela palavra "padeceu"?', 'Que durante toda a sua vida na terra, mas especialmente no fim dela, ele carregou, em corpo e alma, a ira de Deus contra o pecado de toda a humanidade; para que por seu sofrimento, como único sacrifício expiatório, livrasse nosso corpo e nossa alma da condenação eterna e nos alcançasse a graça, a justiça e a vida eterna.', ARRAY['sofrimento de Cristo','expiação','ira de Deus','substituto'], ARRAY['Isaías 53.4-5','1 Pedro 2.24','Colossenses 1.13-14'], 37, '{"full_seed":true}'::jsonb),
    (v_doc_id, 38, '38', 'Por que ele padeceu sob o juiz Pôncio Pilatos?', 'Para que, embora inocente, ele fosse condenado por um juiz secular e com isso nos libertasse do severo julgamento de Deus, que seria exercido sobre nós.', ARRAY['morte de Cristo','condenação','substituto'], ARRAY['Lucas 23.13-24','João 19.12-16'], 38, '{"full_seed":true}'::jsonb),
    (v_doc_id, 39, '39', 'Está dito algo mais na crucificação de Cristo do que se ele tivesse morrido de outra morte?', 'Sim; pois assim fica provado que tomou sobre si a maldição que pesava sobre mim; porque a morte de cruz era maldita por Deus.', ARRAY['crucificação','maldição','Gálatas 3','substituto'], ARRAY['Gálatas 3.13','Deuteronômio 21.23'], 39, '{"full_seed":true}'::jsonb),
    (v_doc_id, 40, '40', 'Por que Cristo teve que humilhar-se até a morte?', 'Porque em razão da justiça e da verdade de Deus a satisfação pelo nosso pecado não podia ser feita de outro modo, a não ser pela morte do Filho de Deus.', ARRAY['humilhação','morte de Cristo','satisfação'], ARRAY['Filipenses 2.8','Hebreus 2.9'], 40, '{"full_seed":true}'::jsonb),
    (v_doc_id, 41, '41', 'Por que foi sepultado?', 'Para com isso provar que tinha realmente morrido.', ARRAY['sepultamento de Cristo','morte real'], ARRAY['Mateus 27.59-60','Atos 13.29'], 41, '{"full_seed":true}'::jsonb),
    (v_doc_id, 42, '42', 'Já que, pois, Cristo morreu por nós, por que ainda temos que morrer?', 'Nossa morte não é pagamento pelo pecado, mas somente morrer para os pecados e entrar na vida eterna.', ARRAY['morte dos crentes','esperança','vida eterna'], ARRAY['João 5.24','Filipenses 1.23'], 42, '{"full_seed":true}'::jsonb),
    (v_doc_id, 43, '43', 'Que proveito nos traz o sacrifício e a morte de Cristo na cruz?', 'Que por seu poder nosso homem velho é crucificado com ele, morto e sepultado; para que os maus apetites da carne não mais reinem em nós, mas que nos ofereçamos a ele em sacrifício de gratidão.', ARRAY['morte de Cristo','crucificação do velho homem','gratidão'], ARRAY['Romanos 6.6','Colossenses 2.12'], 43, '{"full_seed":true}'::jsonb),
    (v_doc_id, 44, '44', 'Por que se acrescenta: "desceu ao inferno"?', 'Para que em minha maior tribulação e tentação eu tenha a certeza e consolo de que meu Senhor Jesus Cristo, pelo seu inexprimível angústia, dores, pavor e trevas infernais que sofreu na alma, tanto quanto na cruz, me redimiu do pavor e das torturas do inferno.', ARRAY['descida ao inferno','angústia de Cristo','expiação'], ARRAY['Isaías 53.10','Salmo 18.5-6'], 44, '{"full_seed":true}'::jsonb),
    (v_doc_id, 45, '45', 'Como nos aproveita a ressurreição de Cristo?', 'Primeiro, pela sua ressurreição ele venceu a morte para que nos pudesse tornar participantes da justiça que havia adquirido para nós por sua morte. Segundo, por seu poder somos agora também ressuscitados para uma nova vida. Terceiro, a ressurreição de Cristo é para nós uma garantia segura de nossa gloriosa ressurreição.', ARRAY['ressurreição de Cristo','justificação','nova vida','esperança'], ARRAY['Romanos 4.25','Colossenses 3.1-4','1 Coríntios 15.20-21'], 45, '{"full_seed":true}'::jsonb),
    (v_doc_id, 46, '46', 'Como entendes as palavras "subiu ao céu"?', 'Que Cristo foi arrebatado dos seus discípulos à vista deles ao céu e está lá por nós até que venha outra vez a julgar os vivos e os mortos.', ARRAY['ascensão','retorno de Cristo','glorificação'], ARRAY['Atos 1.9-11','Hebreus 9.24'], 46, '{"full_seed":true}'::jsonb),
    (v_doc_id, 47, '47', 'Mas Cristo não está, pois, conosco até o fim do mundo, como ele prometeu?', 'Cristo é verdadeiro homem e verdadeiro Deus. Segundo sua natureza humana, ele já não está na terra; mas segundo sua divindade, majestade, graça e Espírito, ele não se afasta de nós.', ARRAY['ascensão','onipresença','duas naturezas'], ARRAY['Mateus 28.20','João 14.16-17'], 47, '{"full_seed":true}'::jsonb),
    (v_doc_id, 48, '48', 'Mas as duas naturezas em Cristo não se separam entre si desta maneira, caso a humanidade não esteja onde está a divindade?', 'Não, pois uma vez que a divindade não tem qualquer delimitação e está presente em toda a parte, é necessário que esteja além da natureza humana que tomou e, contudo, também dentro da mesma e que permaneça pessoalmente unida a ela.', ARRAY['duas naturezas','comunicação de idiomas','onipresença'], ARRAY['Colossenses 2.9','João 3.13'], 48, '{"full_seed":true}'::jsonb),
    (v_doc_id, 49, '49', 'Que proveito nos traz a ascensão de Cristo ao céu?', 'Primeiro, que ele é nosso advogado junto ao Pai no céu. Segundo, que temos nossa carne no céu, como prova segura de que ele, como cabeça, também há de nos levar a ele, seus membros. Terceiro, que ele nos manda seu Espírito como garantia, pelo cujo poder buscamos o que está no alto, e não as coisas que estão na terra.', ARRAY['ascensão','intercessão','Espírito Santo','esperança'], ARRAY['1 João 2.1','João 14.2-3','Colossenses 3.1'], 49, '{"full_seed":true}'::jsonb),
    (v_doc_id, 50, '50', 'O que se acrescenta: "está sentado à destra de Deus"?', 'Que Cristo subiu ao céu por nossa causa, para ali se mostrar como cabeça de sua Igreja cristã, por quem o Pai governa tudo.', ARRAY['sessão de Cristo','reino','cabeça da Igreja'], ARRAY['Efésios 1.20-22','Colossenses 1.18'], 50, '{"full_seed":true}'::jsonb),
    (v_doc_id, 51, '51', 'Que proveito nos traz esta glória de nossa Cabeça, Cristo?', 'Primeiro, que pelo seu Espírito Santo derrama dons celestiais em nós, seus membros. Segundo, que nos defende e conserva com seu poder contra todos os inimigos.', ARRAY['Cristo glorificado','Espírito Santo','defesa'], ARRAY['Atos 2.33','Efésios 4.8'], 51, '{"full_seed":true}'::jsonb),
    (v_doc_id, 52, '52', 'Que consolo te proporciona a volta de Cristo a julgar os vivos e os mortos?', 'Que em toda a aflição e perseguição, com olhar erguido, espere do mesmo juiz que se apresentou antes a Deus em meu favor e tirou de mim toda a maldição, a vinda como juiz do céu, onde só ele, com os seus eleitos, seja arrebatado ao encontro dele e ao gozo eterno e bem-aventurado.', ARRAY['julgamento final','retorno de Cristo','consolo','eleitos'], ARRAY['Mateus 25.32','Filipenses 3.20-21'], 52, '{"full_seed":true}'::jsonb),
    (v_doc_id, 53, '53', 'O que crês sobre o Espírito Santo?', 'Primeiro, que ele é Deus co-eterno com o Pai e o Filho. Segundo, que também é dado a mim para me tornar, pela verdadeira fé, participante de Cristo e de todos os seus benefícios, para me consolar e permanecer comigo eternamente.', ARRAY['Espírito Santo','Trindade','salvação'], ARRAY['Gênesis 1.2','João 14.16','Atos 5.3-4'], 53, '{"full_seed":true}'::jsonb),
    (v_doc_id, 54, '54', 'O que crês sobre a santa Igreja universal?', 'Que o Filho de Deus da raça humana toda, desde o princípio do mundo até o fim, para si escolhe, congrega e conserva, por seu Espírito e Palavra, em unidade de verdadeira fé, uma comunidade eleita para a vida eterna; e que eu sou e permanecerei sempre parte viva desta comunidade.', ARRAY['Igreja','eleição','congregação','Espírito Santo'], ARRAY['Efésios 1.10','João 10.28'], 54, '{"full_seed":true}'::jsonb),
    (v_doc_id, 55, '55', 'O que entendes por "comunhão dos santos"?', 'Primeiro, que todos e cada um dos crentes, como membros, são partícipes de Cristo Senhor e de todos os seus tesouros e dons. Segundo, que cada um está obrigado a usar prontamente seus dons para o bem e salvação dos outros membros.', ARRAY['comunhão dos santos','Igreja','dons','reciprocidade'], ARRAY['1 Coríntios 12.12-13','Romanos 12.5-8'], 55, '{"full_seed":true}'::jsonb),
    (v_doc_id, 56, '56', 'O que crês acerca da remissão dos pecados?', 'Que Deus, por causa do sacrifício de Cristo, não quer me imputar ao meu pecado, nem a condenação eterna com que estou em constante luta; mas que, graciosamente, me conceda a justiça de Cristo e nunca mais queira me lembrar de meu pecado.', ARRAY['remissão de pecados','justificação','graça','imputação'], ARRAY['Salmo 32.1-2','2 Coríntios 5.19','1 João 2.2'], 56, '{"full_seed":true}'::jsonb),
    (v_doc_id, 57, '57', 'Que consolo te proporciona a "ressurreição dos mortos"?', 'Que não só minha alma depois desta vida seja imediatamente arrebatada a Cristo seu cabeça, mas também que esta minha carne, ressuscitada pelo poder de Cristo, seja novamente unida a minha alma e tornada semelhante ao corpo glorioso de Cristo.', ARRAY['ressurreição','esperança','corpo glorioso'], ARRAY['1 Coríntios 15.53-54','Filipenses 3.21'], 57, '{"full_seed":true}'::jsonb),
    (v_doc_id, 58, '58', 'Que consolo te proporciona o artigo sobre "a vida eterna"?', 'Que, assim como já agora sinto no meu coração o início da alegria eterna, após esta vida terei uma bem-aventurança perfeita, que nenhum olho jamais viu, ouvido ouviu, nem entrou no coração do homem — para que nele louve a Deus eternamente.', ARRAY['vida eterna','beatitude','esperança'], ARRAY['1 Coríntios 2.9','2 Coríntios 5.2-3'], 58, '{"full_seed":true}'::jsonb),
    (v_doc_id, 59, '59', 'Mas o que te aproveita agora crer em tudo isso?', 'Que em Cristo sou justo diante de Deus e herdeiro da vida eterna.', ARRAY['fé','justificação','herança','soteriologia'], ARRAY['Habacuque 2.4','João 3.36'], 59, '{"full_seed":true}'::jsonb),
    (v_doc_id, 60, '60', 'Como és justo diante de Deus?', 'Somente pela verdadeira fé em Jesus Cristo: Deus concede e imputa a perfeita satisfação, justiça e santidade de Cristo ao crente, como se jamais ele tivesse tido ou praticado qualquer pecado, e como se ele tivesse cumprido toda a obediência que Cristo cumpriu por mim; tudo isso, desde que eu aceite tal benção pela fé.', ARRAY['justificação','imputação','fé','obediência de Cristo'], ARRAY['Romanos 3.21-26','2 Coríntios 5.21','Filipenses 3.9'], 60, '{"full_seed":true}'::jsonb),
    (v_doc_id, 61, '61', 'Por que dizes que és justo somente pela fé?', 'Não que seja digno de minha fé agradar a Deus; mas porque somente a satisfação, justiça e santidade de Cristo é minha justiça diante de Deus, e eu não posso recebê-la e aplicar-me a não ser pela fé.', ARRAY['justificação','fé','mérito de Cristo'], ARRAY['Romanos 10.10','1 Coríntios 1.30'], 61, '{"full_seed":true}'::jsonb),
    (v_doc_id, 62, '62', 'Mas por que nossas boas obras não podem ser toda a nossa justiça, nem ao menos parte dela diante de Deus?', 'Porque a justiça que pode subsistir diante do julgamento de Deus deve ser completamente perfeita e totalmente conforme à lei divina; mas nossas melhores obras nesta vida são todas imperfeitas e manchadas de pecado.', ARRAY['justificação','obras','imperfeição','lei'], ARRAY['Romanos 3.20','Gálatas 2.16'], 62, '{"full_seed":true}'::jsonb),
    (v_doc_id, 63, '63', 'Como! Acaso nossas boas obras não merecem nada, ainda que Deus prometa recompensá-las nesta vida e na vindoura?', 'Tal recompensa não é por mérito, mas por graça.', ARRAY['obras','graça','recompensa','mérito'], ARRAY['Lucas 17.10','Romanos 11.6'], 63, '{"full_seed":true}'::jsonb),
    (v_doc_id, 64, '64', 'Mas tal ensinamento não torna as pessoas descuidadas e ímpias?', 'Não, pois é impossível que quem for enxertado em Cristo pela verdadeira fé não traga frutos de gratidão.', ARRAY['santificação','boas obras','gratidão','fé'], ARRAY['João 15.5','Romanos 6.1-2'], 64, '{"full_seed":true}'::jsonb),
    (v_doc_id, 65, '65', 'Já que somente a fé nos faz participantes de Cristo e de todos os seus benefícios, de onde vem tal fé?', 'Do Espírito Santo, que pela pregação do santo Evangelho a gera em nosso coração e a fortalece pelo uso dos santos sacramentos.', ARRAY['fé','Espírito Santo','Palavra','sacramentos'], ARRAY['Efésios 2.8','1 Pedro 1.23'], 65, '{"full_seed":true}'::jsonb),
    (v_doc_id, 66, '66', 'O que são os sacramentos?', 'Os sacramentos são sinais e selos sagrados visíveis, instituídos por Deus para que por eles ele nos compreenda melhor e sele para nós a promessa do Evangelho; a saber, que por causa do único sacrifício de Cristo realizado na cruz, ele concede graciosamente a remissão de pecados e a vida eterna a todos os crentes.', ARRAY['sacramentos','sinais','selos','aliança'], ARRAY['Gênesis 17.11','Romanos 4.11'], 66, '{"full_seed":true}'::jsonb),
    (v_doc_id, 67, '67', 'Devem, pois, a Palavra e os sacramentos, ambos, dirigir nossa fé ao sacrifício de Jesus Cristo na cruz como à única fundação da nossa salvação?', 'Sim, de fato; pois o Espírito Santo nos ensina no Evangelho e nos assegura por meio dos santos sacramentos que toda a nossa salvação repousa no único sacrifício que Cristo fez por nós na cruz.', ARRAY['sacramentos','Palavra','sacrifício de Cristo'], ARRAY['Romanos 6.3','1 Coríntios 11.26'], 67, '{"full_seed":true}'::jsonb),
    (v_doc_id, 68, '68', 'Quantos sacramentos instituiu Cristo no Novo Testamento?', 'Dois: o santo Batismo e a santa Ceia do Senhor.', ARRAY['sacramentos','Batismo','Ceia do Senhor'], ARRAY['Mateus 28.19','Mateus 26.26-28'], 68, '{"full_seed":true}'::jsonb),
    (v_doc_id, 69, '69', 'Como na santa Ceia do Senhor te é significado e selado que tens parte no único sacrifício de Cristo na cruz?', 'Assim: que Cristo me ordenou comer deste pão partido e beber deste cálice, e com isso prometeu que seu corpo foi tão certamente oferecido e partido na cruz por mim e seu sangue derramado por mim, quanto certamente vejo com os olhos corporais o pão do Senhor ser partido por mim e o cálice me ser dado.', ARRAY['Ceia do Senhor','corpo e sangue de Cristo','selos'], ARRAY['1 Coríntios 11.23-26'], 69, '{"full_seed":true}'::jsonb),
    (v_doc_id, 70, '70', 'O que significa ser lavado pelo sangue e pelo Espírito de Cristo?', 'Significa ter dos pecados a remissão de Deus por graça, por causa do sangue de Cristo, que ele derramou em seu sacrifício por nós na cruz; e ainda ser renovado pelo Espírito Santo e santificados para ser membros de Cristo, para que mais e mais morramos ao pecado e vivamos a Deus, numa vida sem culpa.', ARRAY['Batismo','sangue de Cristo','Espírito Santo','remissão'], ARRAY['Zacarias 13.1','Ezequiel 36.25-26','Atos 22.16'], 70, '{"full_seed":true}'::jsonb),
    (v_doc_id, 71, '71', 'Onde prometeu Cristo que nos lavará com seu sangue e com seu Espírito tão certamente quanto somos lavados com a água do Batismo?', 'No estabelecimento do Batismo, onde diz: "Portanto ide e ensinai todas as nações, batizando-as em nome do Pai, e do Filho e do Espírito Santo." E: "Quem crer e for batizado será salvo; mas quem não crer será condenado." Tal promessa também se repete onde a Escritura chama o Batismo de "banho regenerador" e de "lavagem dos pecados".', ARRAY['Batismo','promessa','institução'], ARRAY['Mateus 28.19','Marcos 16.16','Tito 3.5','Atos 22.16'], 71, '{"full_seed":true}'::jsonb),
    (v_doc_id, 72, '72', 'A lavagem exterior com água é, pois, a lavagem dos pecados?', 'Não; pois somente o sangue de Jesus Cristo e o Espírito Santo nos limpam de todo o pecado.', ARRAY['Batismo','sangue de Cristo','Espírito Santo','opus operatum'], ARRAY['Mateus 3.11','1 Pedro 3.21'], 72, '{"full_seed":true}'::jsonb),
    (v_doc_id, 73, '73', 'Por que, pois, o Espírito Santo chama o Batismo de "banho regenerador" e de "lavagem dos pecados"?', 'Deus não fala assim sem uma razão grave; mas não só quer que ensinemos que por intermédio do Batismo o sangue e o Espírito de Cristo nos lavam dos pecados, assim como a água lava as imundícies do corpo, mas, sobretudo, quer que asseguremos, por este sinal e penhor divinos, que somos tão verdadeiramente lavados dos nossos pecados espiritualmente, quanto somos lavados externamente com água.', ARRAY['Batismo','sinais','asseguração'], ARRAY['Marcos 16.16','1 Pedro 3.21'], 73, '{"full_seed":true}'::jsonb),
    (v_doc_id, 74, '74', 'Devem também ser batizados os infantes?', 'Sim; pois assim como os infantes de Israel eram circuncidados e por isso recebidos na aliança de Deus e no povo de Deus, assim os infantes cristãos devem ser batizados como sinais da aliança e admitidos na comunidade cristã.', ARRAY['batismo de infantes','aliança','circuncisão'], ARRAY['Gênesis 17.7-14','Colossenses 2.11-12'], 74, '{"full_seed":true}'::jsonb),
    (v_doc_id, 75, '75', 'Como te é significado e selado na santa Ceia que partilhas do único sacrifício de Cristo na cruz e de todos os seus benefícios?', 'Assim: que Cristo me ordenou e a todos os crentes comer deste pão partido e beber deste cálice, e com isso prometeu que seu corpo foi tão certamente oferecido e partido na cruz por mim e seu sangue derramado por mim, quanto certamente vejo com os olhos o pão do Senhor ser partido por mim e o cálice me ser dado.', ARRAY['Ceia do Senhor','sacrifício de Cristo','selos'], ARRAY['Mateus 26.26-28','1 Coríntios 10.16-17'], 75, '{"full_seed":true}'::jsonb),
    (v_doc_id, 76, '76', 'O que significa comer o corpo partido de Cristo e beber seu sangue derramado?', 'Significa não só abraçar com coração crente todo o sofrimento e morte de Cristo, e assim obter a remissão dos pecados e a vida eterna, mas também mais e mais ser unido ao seu corpo santíssimo pelo Espírito Santo, que habita em Cristo e também em nós; de modo que, ainda que Cristo esteja no céu e nós na terra, não obstante somos carne de sua carne e osso de seus ossos e vivemos e somos governados eternamente por um Espírito, assim como os membros de nosso corpo são vivificados por uma só alma.', ARRAY['Ceia do Senhor','união com Cristo','Espírito Santo'], ARRAY['João 6.35','João 6.55-56','Efésios 5.29-30'], 76, '{"full_seed":true}'::jsonb),
    (v_doc_id, 77, '77', 'Onde prometeu Cristo que os crentes serão tão certamente alimentados com seu corpo e seu sangue quanto comem do pão partido e bebem do cálice?', 'No estabelecimento da Ceia: "O Senhor Jesus, na noite em que foi traído, tomou o pão; e, tendo dado graças, o partiu e disse: Tomai, comei; isto é o meu corpo que por vós é partido; fazei isso em memória de mim. Do mesmo modo também o cálice, depois da ceia, dizendo: Este cálice é o novo testamento no meu sangue; fazei isso, todas as vezes que beberdes, em memória de mim." Tal promessa se repete em Paulo: o cálice da bênção que abençoamos não é a comunhão do sangue de Cristo? O pão que partimos não é a comunhão do corpo de Cristo?', ARRAY['Ceia do Senhor','institução','promessa'], ARRAY['1 Coríntios 11.23-25','1 Coríntios 10.16'], 77, '{"full_seed":true}'::jsonb),
    (v_doc_id, 78, '78', 'O pão e o vinho se transformam no corpo e no sangue de Cristo?', 'Não; mas assim como a água do Batismo não se transforma em sangue de Cristo nem é ele mesmo, mas somente é sinal e confirmação de Deus disso, assim também o pão na Ceia do Senhor não se transforma no próprio corpo de Cristo; antes, é chamado corpo de Cristo segundo o hábito dos sacramentos e é sinal e confirmação disso.', ARRAY['Ceia do Senhor','transubstanciação','sinais'], ARRAY['Mateus 26.29','1 Coríntios 10.16'], 78, '{"full_seed":true}'::jsonb),
    (v_doc_id, 79, '79', 'Por que Cristo chama o pão de seu corpo e o cálice de seu sangue, ou de "novo testamento em seu sangue", se o pão e o vinho não se tornam o corpo e o sangue de Cristo?', 'Cristo fala assim não sem grande razão: não somente para nos ensinar que assim como o pão e o vinho sustentam esta vida temporal, assim também seu corpo crucificado e sangue derramado são o verdadeiro alimento e bebida de nossas almas para a vida eterna; mas, sobretudo, quer nos assegurar por este sinal visível e penhor, que nós, pela operação do Espírito Santo, participamos de seu verdadeiro corpo e verdadeiro sangue, tão certamente quanto nossas bocas recebem em sua memória estes sagrados sinais; e que todo o seu sofrimento e obediência nos sejam tão certamente atribuídos como se nós mesmos tivéssemos sofrido e satisfeito a Deus por nossos pecados.', ARRAY['Ceia do Senhor','linguagem sacramental','asseguração'], ARRAY['João 6.51','1 Coríntios 10.16-17'], 79, '{"full_seed":true}'::jsonb),
    (v_doc_id, 80, '80', 'Qual é a diferença entre a Ceia do Senhor e a missa papista?', 'A Ceia do Senhor nos assegura que temos plena remissão de todos os nossos pecados por meio do único sacrifício de Jesus Cristo, que ele mesmo consumou uma vez na cruz, e que somos incorporados a Cristo pelo Espírito Santo, que habita em nós e em Cristo no céu, assentado à destra do Pai; mas a missa ensina que os vivos e os mortos não têm remissão dos pecados por meio do sofrimento de Cristo, a não ser que Cristo seja a cada dia oferecido por eles pelos sacerdotes; e que Cristo está corporalmente presente sob a forma do pão e vinho e que portanto deve ser por eles adorado. A missa é, pois, no fundo, nada mais do que uma negação do único sacrifício e sofrimento de Jesus Cristo e uma abominação maldita.', ARRAY['Ceia do Senhor','missa','sacerdócio de Cristo','sacrifício único'], ARRAY['Hebreus 10.12','Hebreus 7.27'], 80, '{"full_seed":true}'::jsonb),
    (v_doc_id, 81, '81', 'Quem deve participar da Ceia do Senhor?', 'Aqueles que se desgostam de si mesmos por causa de seus pecados e, no entanto, confiam que esses pecados lhes são perdoados e que a fraqueza que resta neles está coberta pela sofrimento e morte de Cristo, e que também desejam cada vez mais fortalecer sua fé e reformar sua vida. Os hipócritas e os que não se arrependem, porém, comem e bebem para si mesmos o julgamento.', ARRAY['Ceia do Senhor','auto-exame','participação digna'], ARRAY['1 Coríntios 11.28-29','1 Coríntios 10.19-22'], 81, '{"full_seed":true}'::jsonb),
    (v_doc_id, 82, '82', 'São admitidos à Ceia do Senhor também aqueles que pela confissão e pela vida se mostram incrédulos e ímpios?', 'Não, pois com isso a aliança de Deus seria profanada e sua ira despertada contra toda a congregação. Portanto, conforme a ordenança de Cristo e seus apóstolos, é obrigação da Igreja cristã excluir tais pessoas por meio das chaves do reino dos céus, até que reformem sua vida.', ARRAY['Ceia do Senhor','disciplina eclesiástica','chaves do reino'], ARRAY['1 Coríntios 11.20','Salmo 50.16'], 82, '{"full_seed":true}'::jsonb),
    (v_doc_id, 83, '83', 'O que são as chaves do reino dos céus?', 'A pregação do santo Evangelho e a disciplina cristã; por essas duas coisas, o reino dos céus é aberto para os crentes e fechado para os incrédulos.', ARRAY['chaves do reino','pregação','disciplina eclesiástica'], ARRAY['Mateus 16.19','João 20.23'], 83, '{"full_seed":true}'::jsonb),
    (v_doc_id, 84, '84', 'Como se abre e fecha o reino dos céus pela pregação do santo Evangelho?', 'Conforme a ordenança de Cristo: o reino dos céus é aberto quando, segundo o mandamento de Cristo, é proclamado e publicamente declarado a todos e a cada um dos crentes que, por causa da fé em Cristo, Deus perdoou verdadeira e sinceramente todos os seus pecados; ao contrário, o reino dos céus é fechado quando é declarado a todos os não-crentes e hipócritas que a ira de Deus e a condenação eterna pousam sobre eles, enquanto não se converterem. Conforme este testemunho do Evangelho, Deus julgará tanto nesta vida como na vindoura.', ARRAY['pregação','Evangelho','chaves do reino'], ARRAY['Mateus 16.19','João 20.21-23'], 84, '{"full_seed":true}'::jsonb),
    (v_doc_id, 85, '85', 'Como se fecha e abre o reino dos céus pela disciplina cristã?', 'Conforme a ordenança de Cristo: aquele que por nome cristão leva uma vida não-cristã e depois de uma repreensão fraternal não se afasta de seus erros, é denunciado à congregação ou aos que são nomeados pela congregação para tal fim; e se também não se emenda depois desta denúncia, é excluído dos santos sacramentos pelo exercício das chaves, e assim excluído do próprio reino de Cristo; mas quando prometer e mostrar com sua emenda verdadeira, ele é admitido como membro de Cristo e de sua Igreja.', ARRAY['disciplina eclesiástica','chaves do reino','excomunhão','restauração'], ARRAY['Mateus 18.15-18','1 Coríntios 5.4-5'], 85, '{"full_seed":true}'::jsonb),
    (v_doc_id, 86, '86', 'Já que somos redimidos de nossa miséria pela graça, somente por intermédio de Cristo sem qualquer mérito nosso, por que ainda devemos fazer boas obras?', 'Porque Cristo, depois de nos ter redimido com seu sangue, também nos renova pela seu Espírito Santo conforme sua imagem, para que com toda a nossa vida mostremos que somos gratos a Deus por seus benefícios e para que ele seja louvado por nós; além disso, para que cada um de nós tenha também para si próprio a certeza de sua fé pelos seus frutos e pelo seu comportamento piedoso ganhe seus vizinhos para Cristo.', ARRAY['boas obras','gratidão','santificação','asseguração'], ARRAY['Efésios 2.10','Mateus 5.16','1 Pedro 2.12'], 86, '{"full_seed":true}'::jsonb),
    (v_doc_id, 87, '87', 'Não podem, pois, ser salvos os que não se convertem de sua vida ingrata e impenitente?', 'De forma alguma; pois a Escritura diz que nenhum impuro, idólatra, adúltero, ladrão, avarento, bêbado, difamador, salteador e semelhantes entrará no reino de Deus.', ARRAY['arrependimento','boas obras','salvação','lei'], ARRAY['1 Coríntios 6.9-10','Gálatas 5.19-21'], 87, '{"full_seed":true}'::jsonb),
    (v_doc_id, 88, '88', 'Em quantas partes consiste a verdadeira conversão do homem?', 'Em duas: a mortificação do velho homem e a vivificação do novo.', ARRAY['conversão','mortificação','vivificação'], ARRAY['Romanos 6.4-6','Efésios 4.22-24'], 88, '{"full_seed":true}'::jsonb),
    (v_doc_id, 89, '89', 'O que é a mortificação do velho homem?', 'Verdadeiro desgosto do coração com os pecados e cada vez mais os odiar e fugir deles.', ARRAY['mortificação','arrependimento','pecado'], ARRAY['Romanos 8.13','Joel 2.13'], 89, '{"full_seed":true}'::jsonb),
    (v_doc_id, 90, '90', 'O que é a vivificação do novo homem?', 'Sincera alegria do coração em Deus por Cristo e amor e prazer em viver segundo a vontade de Deus em toda boa obra.', ARRAY['vivificação','nova vida','gratidão'], ARRAY['Romanos 5.1','Romanos 14.17','Gálatas 2.20'], 90, '{"full_seed":true}'::jsonb),
    (v_doc_id, 91, '91', 'O que são boas obras?', 'Somente as que provêm da verdadeira fé e são feitas conforme a lei de Deus para a sua glória, e não as que se baseiam em nossas opiniões ou em ordenanças humanas.', ARRAY['boas obras','lei','glória de Deus','fé'], ARRAY['Romanos 14.23','1 Coríntios 10.31'], 91, '{"full_seed":true}'::jsonb),
    (v_doc_id, 92, '92', 'Qual é a lei do Senhor?', 'Deus falou todas estas palavras: "Eu sou o Senhor teu Deus, que te tirei da terra do Egito, da casa da servidão. Não terás outros deuses diante de mim..." [Os Dez Mandamentos são aqui citados integralmente, como em Êxodo 20.1-17].', ARRAY['lei','Dez Mandamentos','redenção'], ARRAY['Êxodo 20.1-17','Deuteronômio 5.6-21'], 92, '{"full_seed":true}'::jsonb),
    (v_doc_id, 93, '93', 'Como estão divididos os Dez Mandamentos?', 'Em duas tábuas: a primeira com quatro mandamentos, que nos ensinam como nos comportar para com Deus; a segunda com seis mandamentos, que nos ensinam o que devemos ao próximo.', ARRAY['Dez Mandamentos','duas tábuas','amor a Deus','amor ao próximo'], ARRAY['Mateus 22.37-40','Êxodo 34.28'], 93, '{"full_seed":true}'::jsonb),
    (v_doc_id, 94, '94', 'O que Deus ordena no primeiro mandamento?', 'Que eu, sob pena de perder minha alma e minha salvação, não ponha nem busque minha salvação em mais ninguém ou em mais nada, que só ao único Deus verdadeiro submeta minha confiança correta, humildade, paciência e tudo o que espero de bem; que o ame, tema e honre de todo coração, de tal modo que renuncie a qualquer coisa antes de transgredir sua vontade em qualquer coisa.', ARRAY['1º mandamento','adoração','confiança','monotéismo'], ARRAY['Mateus 4.10','Deuteronômio 6.4-5'], 94, '{"full_seed":true}'::jsonb),
    (v_doc_id, 95, '95', 'O que é idolatria?', 'Idolatria é ter ou venerar no lugar ou ao lado do único Deus verdadeiro qualquer outra coisa em que o homem coloca sua confiança.', ARRAY['idolatria','1º mandamento','ídolos'], ARRAY['Gálatas 4.8-9','Filipenses 3.19'], 95, '{"full_seed":true}'::jsonb),
    (v_doc_id, 96, '96', 'O que Deus quer no segundo mandamento?', 'Que não representemos a Deus de modo algum e não o adoremos de qualquer outra forma que não seja a que ele ordenou em sua Palavra.', ARRAY['2º mandamento','princípio regulador','imagens'], ARRAY['Deuteronômio 4.15-16','Isaías 40.18-19'], 96, '{"full_seed":true}'::jsonb),
    (v_doc_id, 97, '97', 'Não se deve fazer absolutamente nenhuma imagem?', 'Deus não pode nem deve ser representado de forma alguma; quanto às criaturas, embora estas possam ser representadas, Deus proíbe fazer e venerar imagens para adorá-las ou para servir de mediação a seu culto.', ARRAY['2º mandamento','imagens','representação de Deus'], ARRAY['Êxodo 23.24-25','Êxodo 34.13-14'], 97, '{"full_seed":true}'::jsonb),
    (v_doc_id, 98, '98', 'Mas não se pode admitir imagens nas igrejas como "bíblia dos leigos"?', 'Não; pois não devemos ser mais sábios do que Deus, que não quer que o seu povo seja instruído por ídolos mudos, mas pela viva pregação de sua Palavra.', ARRAY['2º mandamento','imagens','pregação','bíblia dos leigos'], ARRAY['Deuteronômio 4.28-29','Habacuque 2.18-19'], 98, '{"full_seed":true}'::jsonb),
    (v_doc_id, 99, '99', 'O que Deus ordena no terceiro mandamento?', 'Que não blasfememos nem profanemos com maldições, falsos juramentos ou obras inúteis o nome de Deus, mas que o usemos com temor e reverência, de modo que ele seja por nós corretamente confessado, invocado e louvado em toda palavra e obra.', ARRAY['3º mandamento','nome de Deus','reverência'], ARRAY['Levítico 24.15-16','Romanos 2.24'], 99, '{"full_seed":true}'::jsonb),
    (v_doc_id, 100, '100', 'O profanar o nome de Deus pelo juramento e pela blasfêmia é pecado tão grave que Deus também se ira com os que não procuram impedi-lo e proibi-lo, na medida em que lhes é possível?', 'Certamente; pois nenhum pecado é maior nem mais fortemente provocador da ira de Deus do que a profanação de seu nome; por isso também ordenou que fosse punido com a morte.', ARRAY['3º mandamento','blasfêmia','gravidade do pecado'], ARRAY['Levítico 5.1','Provérbios 29.24'], 100, '{"full_seed":true}'::jsonb),
    (v_doc_id, 101, '101', 'Mas podemos jurar piedosamente pelo nome de Deus?', 'Sim, quando o governo o exige, ou quando a necessidade pede para assim manter e promover fidelidade e verdade, para a glória de Deus e em benefício do próximo; pois tal juramento está fundado na Palavra de Deus e foi também por isso justamente usado pelos santos na Antiga e na Nova Aliança.', ARRAY['juramento','nome de Deus','governo','verdade'], ARRAY['Deuteronômio 10.20','Hebreus 6.16'], 101, '{"full_seed":true}'::jsonb),
    (v_doc_id, 102, '102', 'Pode-se também jurar por santos ou por outro tipo de criatura?', 'Não; pois juramento legítimo é invocar a Deus como aquele que sozinho conhece o coração, para que ele seja testemunho da verdade e puna o perjúrio; tal honra não compete a nenhuma criatura.', ARRAY['juramento','adoração','nome de Deus'], ARRAY['Mateus 5.34-35','Jeremias 5.7'], 102, '{"full_seed":true}'::jsonb),
    (v_doc_id, 103, '103', 'O que Deus ordena no quarto mandamento?', 'Que a pregação e o ensino do Evangelho seja mantido e que eu vá de forma especial para a congregação de Deus no dia de descanso, no qual aprendo a Palavra de Deus, uso os santos sacramentos, invoco publicamente ao Senhor e dou esmolas cristãs; e que durante toda a minha vida cesse das obras ruins e deixe o Senhor Espírito trabalhar em mim, começo da eterna sabedoria de sábado nesta vida.', ARRAY['4º mandamento','Dia do Senhor','culto','sábado'], ARRAY['Levítico 23.3','1 Coríntios 16.1-2'], 103, '{"full_seed":true}'::jsonb),
    (v_doc_id, 104, '104', 'O que Deus ordena no quinto mandamento?', 'Que eu honre, ame e seja fiel ao meu pai e à minha mãe e a todos que têm autoridade sobre mim; que eu me submeta com devida obediência a toda boa instrução e punição deles, e que também tenha paciência com as fraquezas e falhas deles, já que a Deus agrada governar-nos por sua mão.', ARRAY['5º mandamento','autoridade','honra','obediência'], ARRAY['Efésios 6.1-2','Colossenses 3.20'], 104, '{"full_seed":true}'::jsonb),
    (v_doc_id, 105, '105', 'O que Deus ordena no sexto mandamento?', 'Que eu não insulte, odeie, ofenda nem mate o meu próximo, nem pelo pensamento, palavra ou gesto, nem muito menos pelos meus próprios atos, por meio de outros ou de modo indireto; mas que deponha toda a ira de vingança, que também não prejudique a mim mesmo nem me exponha voluntariamente ao perigo; por isso, também a autoridade está equipada com a espada para coibir o homicídio.', ARRAY['6º mandamento','vida humana','ira','homicídio'], ARRAY['Gênesis 9.6','Efésios 4.26'], 105, '{"full_seed":true}'::jsonb),
    (v_doc_id, 106, '106', 'Mas este mandamento fala somente de matar?', 'Ao proibir o homicídio, Deus nos ensina que ele odeia a raiz deste pecado, a saber, a inveja, o ódio, a ira e o desejo de vingança, e que tudo isso é para ele um assassinato oculto.', ARRAY['6º mandamento','homicídio','ódio','raiz do pecado'], ARRAY['Romanos 1.29','1 João 3.15'], 106, '{"full_seed":true}'::jsonb),
    (v_doc_id, 107, '107', 'Então é suficiente não matarmos o próximo da forma mencionada?', 'Não; pois quando Deus condena a inveja, o ódio e a ira, ele nos ordena que amemos ao próximo como a nós mesmos, que tenhamos com ele paciência, paz, bondade e misericórdia e que o protejamos de todo dano, tanto quanto pudermos.', ARRAY['6º mandamento','amor ao próximo','bondade'], ARRAY['Efésios 4.2','Romanos 12.10'], 107, '{"full_seed":true}'::jsonb),
    (v_doc_id, 108, '108', 'O que o sétimo mandamento nos ensina?', 'Que toda impureza é maldita por Deus e que por isso devemos odiá-la de coração e viver casta e moderadamente, seja no santo matrimônio seja no celibato.', ARRAY['7º mandamento','castidade','pureza','matrimônio'], ARRAY['1 Tessalonicenses 4.3-5','Hebreus 13.4'], 108, '{"full_seed":true}'::jsonb),
    (v_doc_id, 109, '109', 'Deus proíbe no sétimo mandamento somente o adultério e outros atos semelhantes de impureza?', 'Já que nosso corpo e nossa alma são templos do Espírito Santo, Deus quer que mantenhamos ambos em pureza e santidade; por isso proíbe todos os gestos, olhares, palavras, pensamentos, desejos e todo o que pode incitar o homem a isso.', ARRAY['7º mandamento','pureza','tentação','temploDo Espírito'], ARRAY['1 Coríntios 6.18-20','Mateus 5.27-28'], 109, '{"full_seed":true}'::jsonb),
    (v_doc_id, 110, '110', 'O que Deus proíbe no oitavo mandamento?', 'Deus proíbe não só o furto e o roubo aberto, que a lei puna, mas também todo engano perverso e todos os meios e maneiras pelas quais os bens do próximo nos possam ser acrescidos, seja pela força ou pela aparência de licitude; bem como cobrança de juro abusivo, ou qualquer outra maneira proibida por Deus; além de toda a avareza e de todo desperdício de seus dons.', ARRAY['8º mandamento','roubo','injustiça','avareza'], ARRAY['1 Coríntios 6.10','Ezequiel 22.12'], 110, '{"full_seed":true}'::jsonb),
    (v_doc_id, 111, '111', 'O que Deus te ordena no oitavo mandamento?', 'Que promova em tudo e onde puder o benefício e interesse do meu próximo, trate-o como gostaria que me tratassem, além de trabalhar fielmente para poder dar ao necessitado a partir do que precisa.', ARRAY['8º mandamento','generosidade','próximo','mordomia'], ARRAY['Mateus 7.12','Filipenses 2.4'], 111, '{"full_seed":true}'::jsonb),
    (v_doc_id, 112, '112', 'O que o nono mandamento nos ordena?', 'Que nunca dê falso testemunho contra ninguém, não distorça as palavras de ninguém, não seja delator nem caluniador; não julgue nem condene sem ter ouvido o próximo; mas que evite toda mentira e fraude como as obras próprias do diabo, sob pena de ser punido por Deus de modo grave; nos juízos e em toda outra questão, ame a verdade, a fale e a confesse franca e honestamente; defenda e promova a honra e a boa reputação do próximo como puder.', ARRAY['9º mandamento','verdade','calúnia','reputação'], ARRAY['Provérbios 19.5','João 8.44'], 112, '{"full_seed":true}'::jsonb),
    (v_doc_id, 113, '113', 'O que o décimo mandamento nos ordena?', 'Que nem o menor pensamento ou desejo nos venha ao coração contra qualquer mandamento de Deus, mas que sempre odiemos de coração todo o pecado e nos comprazamos na justiça.', ARRAY['10º mandamento','cobiça','coração','contentamento'], ARRAY['Romanos 7.7','Romanos 7.21-23'], 113, '{"full_seed":true}'::jsonb),
    (v_doc_id, 114, '114', 'Mas podem os que se converteram a Deus guardar perfeitamente estes mandamentos?', 'Não; mas os que mais piedosos são, mais começam esta obediência; todavia se propõem a guardar não apenas alguns mas todos os mandamentos de Deus.', ARRAY['santificação','imperfeição','progresso','mandamentos'], ARRAY['1 João 1.8-9','Romanos 7.22-23'], 114, '{"full_seed":true}'::jsonb),
    (v_doc_id, 115, '115', 'Por que, pois, Deus pregoa os Dez Mandamentos tão rigorosamente quando ninguém os pode guardar nesta vida?', 'Primeiro, para que durante toda a nossa vida conheçamos mais e mais nossa natureza pecaminosa e por isso busquemos mais ardentemente a remissão dos pecados e a justiça em Cristo. Segundo, para que nos esforcemos com cuidado e pidamos a Deus a graça do Espírito Santo, para que mais e mais nos renovemos conforme a imagem de Deus, até que após esta vida cheguemos ao alvo da perfeição.', ARRAY['lei','conhecimento do pecado','graça','santificação'], ARRAY['Salmo 32.5','Romanos 7.24-25'], 115, '{"full_seed":true}'::jsonb),
    (v_doc_id, 116, '116', 'Por que os cristãos precisam da oração?', 'Porque ela é a parte mais importante da gratidão que Deus exige de nós, e porque Deus quer conceder sua graça e seu Espírito Santo somente àqueles que, suspirando com sincero coração, pediam sem cessar a ele estas coisas e lho agradeciam.', ARRAY['oração','gratidão','Espírito Santo'], ARRAY['Salmo 50.14-15','Mateus 7.7-8'], 116, '{"full_seed":true}'::jsonb),
    (v_doc_id, 117, '117', 'O que pertence à oração que agrade a Deus e seja por ele ouvida?', 'Primeiro, que invoquemos o único Deus verdadeiro, que se revelou em sua Palavra, por tudo aquilo que ele nos ordenou pedir. Segundo, que reconheçamos de coração perante ele nossa miséria e indignidade, e nos prostremos diante de sua majestade. Terceiro, que tenhamos firme fundamento de que, apesar de nossa indignidade, ouvirá nossa oração por causa de Cristo nosso Senhor, como prometeu em sua Palavra.', ARRAY['oração','invocação','humildade','confiança'], ARRAY['João 4.24','Romanos 8.26'], 117, '{"full_seed":true}'::jsonb),
    (v_doc_id, 118, '118', 'O que Deus nos ordenou pedir?', 'Tudo o que é necessário para o corpo e a alma, que o Senhor Cristo resumiu na oração que ele mesmo nos ensinou.', ARRAY['oração','Pai Nosso','necessidades'], ARRAY['Tiago 1.17','Mateus 6.33'], 118, '{"full_seed":true}'::jsonb),
    (v_doc_id, 119, '119', 'Qual é a oração do Senhor?', 'Pai nosso, que estás nos céus, santificado seja o teu nome. Venha o teu reino. Seja feita a tua vontade, assim na terra como no céu. O pão nosso de cada dia nos dá hoje. E perdoa-nos as nossas dívidas, assim como nós perdoamos aos nossos devedores. E não nos deixes cair em tentação, mas livra-nos do mal. Porque teu é o reino, e o poder, e a glória, para sempre. Amém.', ARRAY['Pai Nosso','oração','modelo'], ARRAY['Mateus 6.9-13','Lucas 11.2-4'], 119, '{"full_seed":true}'::jsonb),
    (v_doc_id, 120, '120', 'Por que Cristo nos ordenou invocar a Deus assim: "Pai nosso"?', 'Para despertar em nós logo no início da oração aquela confiança filial em Deus que deve ser a base de nossa oração: que Deus se tornou por Cristo nosso Pai e nos ouvirá menos que um pai nos rejeitaria quando os filhos pedem alguma coisa. Por isso, é necessário que possamos abandonar tudo o que não é de confiança em Deus e a ele nos aproximar com os nossos pedidos.', ARRAY['Pai Nosso','filiação divina','confiança','oração'], ARRAY['Mateus 7.9-11','Lucas 11.11-13'], 120, '{"full_seed":true}'::jsonb),
    (v_doc_id, 121, '121', 'Por que se acrescenta: "que estás nos céus"?', 'Para que não pensemos de Deus de um modo terreno, e de seu poder onipotente esperemos tudo o que é necessário para a alma e para o corpo.', ARRAY['Pai Nosso','onipotência','transcendência'], ARRAY['Romanos 10.12','Jeremias 23.23-24'], 121, '{"full_seed":true}'::jsonb),
    (v_doc_id, 122, '122', 'O que significa a primeira petição: "Santificado seja o teu nome"?', 'Concede-nos primeiro que te conheçamos corretamente, e que te honremos, glorifiquemos e louvemos em todas as tuas obras, nas quais resplandecem teu poder, sabedoria, bondade, justiça, misericórdia e verdade; e além disso que conduzamos e orientemos toda a nossa vida, pensamentos, palavras e obras de modo que teu nome não seja blasfemado por nossa causa, mas que seja honrado e louvado.', ARRAY['Pai Nosso','glorificação de Deus','conhecimento de Deus'], ARRAY['Salmo 119.137','Romanos 11.36'], 122, '{"full_seed":true}'::jsonb),
    (v_doc_id, 123, '123', 'O que significa a segunda petição: "Venha o teu reino"?', 'Governa-nos pela tua Palavra e Espírito, de modo que cada vez mais nos submetamos a ti; protege e aumenta tua Igreja; destrói as obras do diabo e todo poder que se levanta contra ti e teu plano santo, que inclui tudo, até que a perfeição de teu reino se manifeste, na qual tu serás tudo em todos.', ARRAY['Pai Nosso','reino de Deus','Igreja','escatologia'], ARRAY['Salmo 119.5','Romanos 10.14-15'], 123, '{"full_seed":true}'::jsonb),
    (v_doc_id, 124, '124', 'O que significa a terceira petição: "Seja feita a tua vontade, assim na terra como no céu"?', 'Concede que nós e todos os homens renunciemos à nossa vontade própria e, sem murmúrio, obedeçamos à tua vontade, que é a única boa; de modo que cada qual cumpra seu dever e vocação tão fiel e voluntariamente quanto os anjos no céu.', ARRAY['Pai Nosso','vontade de Deus','obediência'], ARRAY['Romanos 12.2','Tito 2.11-12'], 124, '{"full_seed":true}'::jsonb),
    (v_doc_id, 125, '125', 'O que significa a quarta petição: "O pão nosso de cada dia nos dá hoje"?', 'Provê-nos de tudo o que é necessário para nosso corpo, para que com isso reconheçamos que tu és o único fonte de todo bem e que sem tua bênção não podem nada nossas preocupações e trabalho, e nem teus dons; e que por isso afastemos de nós toda a confiança das criaturas e a depositemos somente em ti.', ARRAY['Pai Nosso','providência','pão','contentamento'], ARRAY['Salmo 104.27-30','Mateus 6.25-26'], 125, '{"full_seed":true}'::jsonb),
    (v_doc_id, 126, '126', 'O que significa a quinta petição: "Perdoa-nos as nossas dívidas, assim como nós perdoamos aos nossos devedores"?', 'Por causa do sangue de Cristo, não nos imputes a nós, pecadores miseráveis, nossas iniqüidades, nem a corrupção que ainda está em nós; assim como também nós encontramos em nós este testemunho da tua graça, que estamos plenamente dispostos a perdoar ao próximo de coração.', ARRAY['Pai Nosso','perdão','graça','sangue de Cristo'], ARRAY['Salmo 51.1-2','Mateus 6.14-15'], 126, '{"full_seed":true}'::jsonb),
    (v_doc_id, 127, '127', 'O que significa a sexta petição: "E não nos deixes cair em tentação, mas livra-nos do mal"?', 'Como em nós mesmos somos tão fracos que não podemos ficar de pé por um instante sequer, e além disso nossos inimigos, o diabo, o mundo e nossa própria carne, nunca cessam de nos atacar; guarda-nos e fortalece-nos pelo poder de teu Espírito Santo, de modo que nos não curvemos a eles em luta resoluta, até que finalmente obtenhamos a vitória completa.', ARRAY['Pai Nosso','tentação','Espírito Santo','perseverança'], ARRAY['1 Coríntios 10.13','1 Tessalonicenses 5.23'], 127, '{"full_seed":true}'::jsonb),
    (v_doc_id, 128, '128', 'Como se conclui esta oração?', '"Porque teu é o reino, e o poder, e a glória, para sempre."', ARRAY['Pai Nosso','doxologia','conclusão'], ARRAY['1 Crônicas 29.11-12'], 128, '{"full_seed":true}'::jsonb),
    (v_doc_id, 129, '129', 'O que significa a palavra "Amém"?', 'Amém significa: será assim e será certo; pois minha oração foi ouvida por Deus com muito maior certeza do que sinto em meu coração que a desejo.', ARRAY['Pai Nosso','amém','confiança','certeza'], ARRAY['2 Coríntios 1.20','Apocalipse 22.20'], 129, '{"full_seed":true}'::jsonb)
